/*
 * Surroundflix page hook. Generated by the Python builder; edit the
 * template in src/surroundflix/templates/page.js, not the build output.
 *
 * Cadmium (Netflix's player) serialises its manifest request with
 * JSON.stringify before encrypting and sending it. That request carries a
 * "profiles" list of the formats the browser claims to support. We wrap
 * JSON.stringify and append extra audio profiles to that list. Netflix's
 * own code is never modified, so a new Cadmium version doesn't break this
 * unless Netflix changes the request format itself.
 *
 * DRM is untouched: audio still comes through Netflix's normal, licensed
 * playback path.
 */
(function () {
  "use strict";

  var CONFIG = /*__SURROUNDFLIX_CONFIG__*/ null;
  if (!CONFIG || window.__surroundflix) return;

  // Prefixes Netflix uses for audio profile names. A "profiles" array is
  // only touched if it already contains one of these, so unrelated data
  // that happens to use the same key is left alone.
  var AUDIO_PROFILE = /^(heaac|xheaac|ddplus)-/;
  var MANIFEST_KEYS = ["params", "profiles", "profileGroups"];
  var MAX_DEPTH = 5;
  // The extension writes the choices made in its popup here.
  var PRESET_ATTR = "data-surroundflix-preset";
  var VIDEO_ATTR = "data-surroundflix-video";
  // Video quality modes, by name. "auto" leaves Netflix's list alone.
  var VIDEO_MODES = {
    auto: {},
    min720: { minHeight: 720 },
    min1080: { minHeight: 1080 },
    min2160: { minHeight: 2160 },
    best: { best: true },
    saver720: { maxHeight: 720 }
  };

  var state = {
    version: CONFIG.version,
    preset: CONFIG.preset,
    dolbySupported: null,
    requested: [],
    patchedRequests: 0,
    lastPatchedAt: null,
    lastManifestAudio: null,
    lastManifestVideo: null,
    titlesWithBadges: 0
  };

  // Mirrors the state into an attribute on <html> so the content script,
  // and through it the popup, can read it from its isolated world.
  var STATUS_ATTR = "data-surroundflix-status";
  function publishStatus() {
    var root = document.documentElement;
    if (!root || !root.setAttribute) return;
    root.setAttribute(STATUS_ATTR, nativeStringify({
      preset: state.preset,
      requested: state.requested,
      received: state.lastManifestAudio,
      video: state.lastManifestVideo,
      patchedRequests: state.patchedRequests
    }));
  }

  function log() {
    if (!CONFIG.debug) return;
    var args = Array.prototype.slice.call(arguments);
    args.unshift("[Surroundflix]");
    console.log.apply(console, args);
  }

  function dolbySupported() {
    if (!CONFIG.checkDolby) return true;
    if (state.dolbySupported === null) {
      try {
        state.dolbySupported = !!(window.MediaSource &&
          window.MediaSource.isTypeSupported('audio/mp4; codecs="ec-3"'));
      } catch (err) {
        state.dolbySupported = false;
      }
    }
    return state.dolbySupported;
  }

  function currentPreset() {
    var root = document.documentElement;
    var chosen = root && root.getAttribute(PRESET_ATTR);
    // The attribute can be set by any script on the page: accept only our
    // own preset names (not "constructor", "__proto__"...).
    return chosen && Object.prototype.hasOwnProperty.call(CONFIG.presets, chosen) ? chosen : CONFIG.preset;
  }

  // The video mode chosen in the popup (or set by the build, for the
  // userscript). Only our own mode names are accepted.
  function videoMode() {
    var root = document.documentElement;
    var value = root && root.getAttribute(VIDEO_ATTR);
    if (value && Object.prototype.hasOwnProperty.call(VIDEO_MODES, value)) return value;
    return Object.prototype.hasOwnProperty.call(VIDEO_MODES, CONFIG.videoQuality) ? CONFIG.videoQuality : "auto";
  }

  // Read at request time, so a change in the popup applies to the next title.
  function wantedProfiles() {
    if (!dolbySupported()) return CONFIG.noDolbyProfiles;
    state.preset = currentPreset();
    return CONFIG.presets[state.preset];
  }

  function isAudioProfileList(arr) {
    if (!Array.isArray(arr)) return false;
    for (var i = 0; i < arr.length; i++) {
      if (typeof arr[i] === "string" && AUDIO_PROFILE.test(arr[i])) return true;
    }
    return false;
  }

  function addProfiles(arr, wanted) {
    var added = 0;
    for (var i = 0; i < wanted.length; i++) {
      if (arr.indexOf(wanted[i]) === -1) {
        arr.push(wanted[i]);
        added++;
      }
    }
    return added;
  }

  // Handles both the flat params.profiles shape and the newer
  // params.profileGroups[].profiles one.
  function walk(node, wanted, depth) {
    if (!node || typeof node !== "object" || depth > MAX_DEPTH) return 0;
    var added = 0;
    if (Array.isArray(node)) {
      for (var i = 0; i < node.length; i++) added += walk(node[i], wanted, depth + 1);
      return added;
    }
    var keys = Object.keys(node);
    for (var k = 0; k < keys.length; k++) {
      var value = node[keys[k]];
      if (keys[k] === "profiles" && isAudioProfileList(value)) {
        added += addProfiles(value, wanted);
      } else if (value && typeof value === "object") {
        added += walk(value, wanted, depth + 1);
      }
    }
    return added;
  }

  function looksLikeManifestRequest(value) {
    if (!value || typeof value !== "object" || Array.isArray(value)) return false;
    for (var i = 0; i < MANIFEST_KEYS.length; i++) {
      if (Object.prototype.hasOwnProperty.call(value, MANIFEST_KEYS[i])) return true;
    }
    return false;
  }

  // Records which audio profiles Netflix actually sent back, so users can
  // paste window.__surroundflix into a bug report. The manifest's shape has
  // changed over the years (audio_tracks / audioTracks, streams /
  // downloadables, nested under result or payload), so search for it.
  var AUDIO_TRACK_KEYS = ["audio_tracks", "audioTracks"];
  var VIDEO_TRACK_KEYS = ["video_tracks", "videoTracks"];
  var STREAM_KEYS = ["streams", "downloadables"];
  var PROFILE_KEYS = ["content_profile", "contentProfile", "profile"];
  var BITRATE_KEYS = ["bitrate", "bitrateKbps"];
  var HEIGHT_KEYS = ["res_h", "height", "resH"];

  function findTracks(node, names, depth) {
    if (!node || typeof node !== "object" || depth > 6) return null;
    var i;
    if (Array.isArray(node)) {
      for (i = 0; i < node.length && i < 50; i++) {
        var found = findTracks(node[i], names, depth + 1);
        if (found) return found;
      }
      return null;
    }
    for (i = 0; i < names.length; i++) {
      var tracks = node[names[i]];
      if (Array.isArray(tracks) && tracks.length) return tracks;
    }
    var keys = Object.keys(node);
    for (i = 0; i < keys.length; i++) {
      var value = node[keys[i]];
      if (value && typeof value === "object") {
        var deeper = findTracks(value, names, depth + 1);
        if (deeper) return deeper;
      }
    }
    return null;
  }

  function firstKey(obj, names) {
    for (var i = 0; i < names.length; i++) {
      if (obj && obj[names[i]] != null) return obj[names[i]];
    }
    return null;
  }

  function audioProfilesOf(tracks) {
    var seen = [];
    function add(cp) {
      if (typeof cp === "string" && AUDIO_PROFILE.test(cp) && seen.indexOf(cp) === -1) seen.push(cp);
    }
    for (var i = 0; i < tracks.length; i++) {
      add(firstKey(tracks[i], PROFILE_KEYS));
      var streams = firstKey(tracks[i], STREAM_KEYS);
      if (!Array.isArray(streams)) continue;
      for (var j = 0; j < streams.length; j++) add(firstKey(streams[j], PROFILE_KEYS));
    }
    return seen;
  }

  function inspectAudio(value) {
    var tracks = findTracks(value, AUDIO_TRACK_KEYS, 0);
    if (!tracks) return false;
    var seen = audioProfilesOf(tracks);
    if (!seen.length) {
      log("audio tracks found but no profile names; first track keys:", Object.keys(tracks[0] || {}));
      return false;
    }
    state.lastManifestAudio = seen;
    log("audio profiles returned by Netflix:", seen);
    return true;
  }

  function number(value) {
    return typeof value === "number" && isFinite(value) && value > 0 ? value : null;
  }

  // Replaces the contents of `list` in place (other code may hold it).
  function replaceAll(list, kept) {
    if (kept === list || kept.length === list.length) return;
    var copy = kept.slice();
    list.length = 0;
    Array.prototype.push.apply(list, copy);
  }

  // Which video streams to keep for a mode. Never returns an empty list: if
  // nothing meets a minimum (or maximum), the closest streams are kept.
  function pickVideo(streams, mode) {
    var rule = VIDEO_MODES[mode];
    function rate(s) { return number(firstKey(s, BITRATE_KEYS)); }
    function height(s) { return number(firstKey(s, HEIGHT_KEYS)); }
    if (rule.best) {
      var top = Math.max.apply(null, streams.map(function (s) { return rate(s) || 0; }));
      return top > 0 ? streams.filter(function (s) { return rate(s) === top; }) : streams;
    }
    var heights = streams.map(height).filter(function (h) { return h !== null; });
    if (heights.length !== streams.length) return streams; // unknown sizes: leave alone
    if (rule.minHeight) {
      var high = streams.filter(function (s) { return height(s) >= rule.minHeight; });
      if (high.length) return high;
      var tallest = Math.max.apply(null, heights);
      return streams.filter(function (s) { return height(s) === tallest; });
    }
    if (rule.maxHeight) {
      var low = streams.filter(function (s) { return height(s) <= rule.maxHeight; });
      if (low.length) return low;
      var shortest = Math.min.apply(null, heights);
      return streams.filter(function (s) { return height(s) === shortest; });
    }
    return streams;
  }

  // Records the video Netflix offers and applies the chosen mode by removing
  // streams from the list the player picks from. Netflix's player itself is
  // untouched: it just gets a shorter list.
  function handleVideo(value, mode) {
    var tracks = findTracks(value, VIDEO_TRACK_KEYS, 0);
    if (!tracks) return false;
    var offered = [], kept = [], total = 0;
    for (var i = 0; i < tracks.length; i++) {
      var streams = firstKey(tracks[i], STREAM_KEYS);
      if (!Array.isArray(streams) || !streams.length) continue;
      total += streams.length;
      Array.prototype.push.apply(offered, streams);
      if (mode !== "auto" && streams.length > 1) replaceAll(streams, pickVideo(streams, mode));
      Array.prototype.push.apply(kept, streams);
    }
    function rate(s) { return number(firstKey(s, BITRATE_KEYS)); }
    function height(s) { return number(firstKey(s, HEIGHT_KEYS)); }
    var best = null;
    kept.forEach(function (s) {
      if (rate(s) !== null && (best === null || rate(s) > rate(best))) best = s;
    });
    if (!best) return false;
    var heights = offered.map(height).filter(function (h) { return h !== null; });
    state.lastManifestVideo = {
      mode: mode,
      bitrate: rate(best),
      height: height(best),
      minHeight: heights.length ? Math.min.apply(null, heights) : null,
      maxHeight: heights.length ? Math.max.apply(null, heights) : null,
      streams: total,
      kept: kept.length
    };
    log("video", mode, state.lastManifestVideo);
    return true;
  }

  // "Always the best" also keeps only the highest bitrate of each audio
  // format (Netflix sometimes offers a format at several bitrates). Formats
  // aren't mixed: the 5.1 / Atmos choice stays the player's.
  function lockAudioBitrate(value) {
    var tracks = findTracks(value, AUDIO_TRACK_KEYS, 0) || [];
    tracks.forEach(function (track) {
      var streams = firstKey(track, STREAM_KEYS);
      if (!Array.isArray(streams) || streams.length < 2) return;
      var top = {};
      streams.forEach(function (s) {
        var key = String(firstKey(s, PROFILE_KEYS));
        var r = number(firstKey(s, BITRATE_KEYS));
        if (r !== null && (!(key in top) || r > top[key])) top[key] = r;
      });
      replaceAll(streams, streams.filter(function (s) {
        var key = String(firstKey(s, PROFILE_KEYS));
        var r = number(firstKey(s, BITRATE_KEYS));
        return r === null || !(key in top) || r === top[key];
      }));
    });
  }

  function handleManifest(value) {
    var mode = videoMode();
    if (mode === "best") lockAudioBitrate(value);
    var audio = inspectAudio(value);
    var video = handleVideo(value, mode);
    if (audio || video) publishStatus();
    return audio || video;
  }

  // Title badges. Netflix sends every title's features ("playbackBadges":
  // AUDIO_DOLBY_ATMOS, AUDIO_FIVE_DOT_ONE, VIDEO_ULTRA_HD...) but its page
  // only draws those it thinks this browser can play, so Atmos, 5.1 and 4K
  // never show in Safari. We add them next to Netflix's own badges, with
  // Netflix's badge class so they look the same.
  var BADGES = [
    { id: "uhd", feature: "VIDEO_ULTRA_HD", label: "Ultra HD 4K" },
    { id: "atmos", feature: "AUDIO_DOLBY_ATMOS", label: "Dolby Atmos" },
    { id: "5.1", feature: "AUDIO_FIVE_DOT_ONE", label: "5.1" }
  ];
  var BADGE_ATTR = "data-surroundflix-badge";
  var LINE_ATTR = "data-surroundflix-badges";
  var METADATA_LINE = ".videoMetadata--line";
  var HD_BADGE = '[data-uia="player-feature-badge-hd"]';
  // Netflix's own items in a metadata line, in the order they appear. Ours
  // go after the last one present.
  var NATIVE_ITEMS = [".year", ".duration", ".maturity-rating", ".player-feature-badge",
    ".svg-icon-dolby-vision", ".spatial-audio"];
  var MAX_TITLES = 5000;
  var featuresById = {};
  var titleCount = 0;

  // Finds every object with a videoId and a playbackBadges list.
  function collectBadges(node, depth) {
    if (!node || typeof node !== "object" || depth > 8) return 0;
    var found = 0, i;
    if (Array.isArray(node)) {
      for (i = 0; i < node.length && i < 500; i++) found += collectBadges(node[i], depth + 1);
      return found;
    }
    var id = node.videoId;
    if (Array.isArray(node.playbackBadges) && (typeof id === "number" || typeof id === "string") &&
        /^\d+$/.test(String(id))) {
      if (!Object.prototype.hasOwnProperty.call(featuresById, String(id))) {
        if (titleCount >= MAX_TITLES) return found;
        titleCount++;
      }
      featuresById[String(id)] = node.playbackBadges.filter(function (b) { return typeof b === "string"; });
      found++;
    }
    var keys = Object.keys(node);
    for (i = 0; i < keys.length; i++) {
      var value = node[keys[i]];
      if (value && typeof value === "object") found += collectBadges(value, depth + 1);
    }
    return found;
  }

  // Which of our badges a title gets in this browser: 4K needs Safari
  // (FairPlay), Atmos needs a Dolby decoder and the "5.1 and Atmos" choice,
  // 5.1 plays everywhere (AAC 5.1 in Chrome). An Atmos title shows Atmos
  // only, like Netflix's apps do.
  function badgesFor(features) {
    var atmosWanted = dolbySupported() &&
      CONFIG.presets[currentPreset()].indexOf("ddplus-atmos-dash") !== -1;
    var hasAtmos = atmosWanted && features.indexOf("AUDIO_DOLBY_ATMOS") !== -1;
    return BADGES.filter(function (b) {
      if (features.indexOf(b.feature) === -1) return false;
      if (b.id === "uhd") return !CONFIG.checkDolby;
      if (b.id === "atmos") return hasAtmos;
      return !hasAtmos;
    });
  }

  function trackedVideoId(text) {
    try {
      text = decodeURIComponent(text || "");
    } catch (err) {
      return null;
    }
    var m = /"video_id":(\d+)/.exec(text);
    return m ? m[1] : null;
  }

  // The title a metadata line belongs to: the tracking data Netflix puts in
  // each card and in the details modal, or else the ?jbv= of the open modal.
  function videoIdFor(line) {
    var node = line;
    for (var depth = 0; depth < 7 && node.parentElement; depth++) {
      node = node.parentElement;
      // Past this point we'd be reading another title's card.
      if (node.querySelectorAll(METADATA_LINE).length > 1) break;
      var tracked = node.querySelectorAll("[data-ui-tracking-context]");
      for (var i = 0; i < tracked.length; i++) {
        var id = trackedVideoId(tracked[i].getAttribute("data-ui-tracking-context"));
        if (id) return id;
      }
    }
    var m = /[?&]jbv=(\d+)/.exec((window.location && window.location.search) || "");
    return m ? m[1] : null;
  }

  function matchesAny(el, selectors) {
    for (var i = 0; i < selectors.length; i++) {
      if (el.matches(selectors[i])) return true;
    }
    return false;
  }

  function lastNativeItem(line) {
    var last = null;
    for (var i = 0; i < line.children.length; i++) {
      var child = line.children[i];
      if (!child.hasAttribute(BADGE_ATTR) && matchesAny(child, NATIVE_ITEMS)) last = child;
    }
    return last;
  }

  function nativeLabels(line) {
    var labels = [];
    var items = line.querySelectorAll(".player-feature-badge");
    for (var i = 0; i < items.length; i++) {
      if (!items[i].hasAttribute(BADGE_ATTR)) labels.push(String(items[i].textContent).trim());
    }
    return labels;
  }

  function drawBadges(line) {
    var id = videoIdFor(line);
    var features = id && featuresById[id];
    if (!features) return;
    var native = nativeLabels(line);
    var wanted = badgesFor(features).filter(function (b) { return native.indexOf(b.label) === -1; });
    var key = id + ":" + wanted.map(function (b) { return b.id; }).join(",");
    var ours = line.querySelectorAll("[" + BADGE_ATTR + "]");
    // React may reuse the line for another title or drop our nodes.
    if (line.getAttribute(LINE_ATTR) === key && ours.length === wanted.length) return;
    for (var i = 0; i < ours.length; i++) line.removeChild(ours[i]);
    var hd = line.querySelector(HD_BADGE);
    if (hd) hd.style.display = "";
    var anchor = lastNativeItem(line);
    wanted.forEach(function (b) {
      var badge = document.createElement("span");
      badge.className = "player-feature-badge";
      badge.setAttribute(BADGE_ATTR, b.id);
      badge.textContent = b.label;
      line.insertBefore(badge, anchor ? anchor.nextSibling : null);
      anchor = badge;
      // "Ultra HD 4K" replaces Netflix's "HD".
      if (b.id === "uhd" && hd) hd.style.display = "none";
    });
    line.setAttribute(LINE_ATTR, key);
  }

  function drawAllBadges() {
    var lines = document.querySelectorAll(METADATA_LINE);
    for (var i = 0; i < lines.length; i++) drawBadges(lines[i]);
  }

  var badgeTimer = null;
  function drawBadgesSoon() {
    if (badgeTimer !== null || !document.querySelectorAll) return;
    badgeTimer = setTimeout(function () {
      badgeTimer = null;
      try {
        drawAllBadges();
      } catch (err) {
        log("badges skipped:", err);
      }
    }, 100);
  }

  function inspectBadges(value) {
    if (collectBadges(value, 0) > 0) {
      state.titlesWithBadges = titleCount;
      drawBadgesSoon();
    }
  }

  function watchPage() {
    if (typeof window.MutationObserver !== "function" || !document.documentElement ||
        !document.querySelectorAll) return;
    new window.MutationObserver(drawBadgesSoon)
      .observe(document.documentElement, { childList: true, subtree: true });
  }

  function mentionsTracks(text) {
    return text.indexOf("audio_tracks") !== -1 || text.indexOf("audioTracks") !== -1 ||
      text.indexOf("video_tracks") !== -1 || text.indexOf("videoTracks") !== -1;
  }

  var nativeStringify = JSON.stringify;
  var nativeParse = JSON.parse;

  function stringify(value, replacer, space) {
    try {
      if (looksLikeManifestRequest(value)) {
        var wanted = wantedProfiles();
        var added = walk(value, wanted, 0);
        if (added > 0) {
          state.requested = wanted.slice();
          state.patchedRequests++;
          state.lastPatchedAt = new Date().toISOString();
          publishStatus();
          log("manifest request patched, added", added, "profile(s)", wanted);
        }
      }
    } catch (err) {
      log("patch skipped:", err);
    }
    return nativeStringify.call(this, value, replacer, space);
  }

  function parse(text, reviver) {
    var result = nativeParse.call(this, text, reviver);
    try {
      if (result && typeof result === "object" && typeof text === "string") {
        if (mentionsTracks(text) && !handleManifest(result)) {
          log("response mentions tracks but none were read; top-level keys:", Object.keys(result));
        }
        if (text.indexOf("playbackBadges") !== -1) inspectBadges(result);
      }
    } catch (err) {
      log("inspect skipped:", err);
    }
    return result;
  }

  // Some responses are decoded with fetch's Response.json(), which doesn't
  // go through JSON.parse.
  var nativeResponseJson = window.Response && window.Response.prototype.json;
  if (nativeResponseJson) {
    window.Response.prototype.json = function () {
      return nativeResponseJson.call(this).then(function (data) {
        try {
          if (data && typeof data === "object") {
            handleManifest(data);
            inspectBadges(data);
          }
        } catch (err) {
          log("inspect skipped:", err);
        }
        return data;
      });
    };
    window.Response.prototype.json.toString = function () { return nativeResponseJson.toString(); };
  }

  // Keep the wrappers looking like the originals to other page code.
  stringify.toString = function () { return nativeStringify.toString(); };
  parse.toString = function () { return nativeParse.toString(); };

  JSON.stringify = stringify;
  JSON.parse = parse;

  Object.defineProperty(window, "__surroundflix", { value: state, configurable: false });
  publishStatus();
  watchPage();
  log("active, default preset", CONFIG.preset);
})();
